AscensionPTBR = AscensionPTBR or {}
local T = AscensionPTBR.TipPairs

T[1]={"^Absorbs (.-) damage%.%s*$","Absorve {{1}} dano."}
T[2]={"^Decreases attack power by (.-)%.%s*$","Reduz o poder de ataque em {{1}}."}
T[3]={"^Able to breathe underwater and swim speed increased%.%s*$","Permite respirar debaixo d'água e aumenta a velocidade de natação."}
T[4]={"^Reduced threat level, and reduces the duration of Stun effects by 30%%%.%s*$","Reduz o nível de ameaça e reduz a duração dos efeitos de Aturdimento em 30%."}
T[5]={"^Reduces magic damage taken by (.-)%% and healing by (.-)%%%.%s*$","Reduz o dano mágico recebido em {{1}}% e a cura em {{2}}%."}
T[6]={"^Charmed%. Time between attacks increased by (.-)%%%.%s*$","Encantado. O tempo entre ataques aumenta em {{1}}%."}
T[7]={"^Immune to all attacks and spells, but reduces all healing and damage you deal by (.-)%%%.%s*$","Imune a todos ataques e feitiços, mas reduz em {{1}}% toda a cura e o dano causados por você."}
T[8]={"^Allows one%-hand and off%-hand weapons to be equipped in the off%-hand%.%s*$","Permite que as armas de uma mão e as armas de mão secundária se equipem como armas de mão secundária."}
T[9]={"^Increases armor by (.-) and healing received by (.-)%%%.%s*$","Aumenta a armadura em {{1}} e a cura recebida em {{2}}%."}
T[10]={"^Attack power reduced by (.-), and armor is reduced by (.-)%%%.%s*$","Poder de Ataque reduzido em {{1}} e a armadura é reduzida em {{2}}%."}
T[11]={"^Heals nearby group members for (.-) every (.-) seconds%. Immune to stun, interrupt and silence effects%.%s*$","Cura os membros próximos do grupo em {{1}} a cada {{2}} segundos. Imune a atordoamento, interrupção e silêncio."}
T[12]={"^Increases melee attack power by (.-) plus 25%% of Agility%.%s*$","Aumenta o poder de ataque corpo a corpo em {{1}} mais 25% de agilidade."}
T[14]={"^Reduces casting or channeling time lost when damaged by (.-)%% and attacks heal the shielded target for (.-) %(doubled against monsters%)%.%s*$","Reduz o tempo perdido ao lançar ou canalizar ao receber dano em {{1}}% e os ataques curam o alvo blindado em {{2}} (o dobro contra monstros)."}
T[15]={"^Increases magic damage taken by (.-)%% and healing by (.-)%%%.%s*$","Aumenta o dano mágico recebido em {{1}}% e a cura em {{2}}%."}
T[16]={"^Immune to physical attacks, Interrupt and Silence mechanics%.  Cannot attack or use physical abilities%.%s*$","Imune aos ataques físicos, interrupções e silenciamentos. Não pode atacar nem usar habilidades físicas."}
T[17]={"^Attempts to dispel 2 harmful magic effects and reduces total threat by (.-)%% every second%.%s*$","Tenta se livrar de 2 efeitos mágicos nocivos e reduz a ameaça total em {{1}}% a cada segundo."}
T[18]={"^(.-) Shadow damage every (.-) seconds%.%s*$","{{1}} dano de Sombra a cada {{2}} segundos."}
T[19]={"^Increases Intellect by (.-) and spell power by (.-)%.%s*$","Aumenta o intelecto em {{1}} e o Poder Mágico em {{2}}."}
T[20]={"^Reduces Arcane, Fire, Frost, Holy, Nature, and Shadow resistances by (.-)%.  Increases magic damage taken by (.-)%%%.%s*$","Reduz as resistências a Arcano, Fogo, Gelo, Sagrado, Natureza e Sombras em {{1}}. Aumenta o dano mágico recebido em {{2}}%."}
T[21]={"^Your attack speed is increased by (.-)%%, but all damage taken is increased by (.-)%%%. Your next (.-) non%-periodic Warrior abilites have an additional (.-)%% to critically hit, (.-) yards extra range and will cause you to charge toward your enemy if not in melee range already%.\n\nCharges are not consumed versus monsters%.\n\nWhile active, the duration of stun and movement impairing effects on you is reduced by (.-)%%%.%s*$","Sua velocidade de ataque aumenta em {{1}}%, mas todo o dano recebido também aumenta em {{2}}%. Suas próximas {{3}} habilidades não periódicas de Guerreiro têm {{4}}% de chance adicional de acerto crítico e {{5}} metros de alcance extra, e fazem você avançar contra o inimigo caso ainda não esteja ao alcance corpo a corpo.\n\nAs cargas não são consumidas contra monstros.\n\nEnquanto estiver ativa, a duração dos efeitos de atordoamento e redução de movimento em você diminui em {{6}}%."}
T[23]={"^Increases movement speed by 50%% while in Cat Form%.%s*$","Aumenta a velocidade de movimento em 50% enquanto estiver em Forma de Felino."}
T[24]={"^Increases movement speed by 60%% while in Cat Form%.%s*$","Aumenta a velocidade de movimento em 60% enquanto estiver em Forma de Felino."}
T[25]={"^Increases movement speed by 70%% while in Cat Form%.%s*$","Aumenta a velocidade de movimento em 70% enquanto estiver em Forma de Felino."}
T[26]={"^Block chance increased by (.-)%% and block value increased by (.-)%%%.%s*$","Aumenta a chance de bloqueio em {{1}}% e o valor do bloqueio em {{2}}%."}
T[27]={"^Increases movement speed by (.-)%%, regenerates (.-)%% of your maximum health every 5 sec\nEffects that reduce movement speed may not bring you below your normal movement speed%.%s*$","Aumenta a velocidade de movimento em {{1}}%, regenera {{2}}% de sua vida máxima a cada 5 s\nOs efeitos que reduzem a velocidade de movimento não podem levar você abaixo de sua velocidade normal de movimento."}
T[28]={"^Increases movement speed by (.-)%%\nEffects that reduce movement speed may not bring you below your normal movement speed%.%s*$","Aumenta a velocidade de movimento em {{1}}%\nOs efeitos que reduzem a velocidade de movimento não podem levar você abaixo de sua velocidade normal de movimento."}
T[29]={"^Attempts to dispel (.-) curse every (.-) seconds%.%s*$","Tenta dissipar {{1}} maldição a cada {{2}} segundos."}
T[30]={"^Increases melee and ranged attack speed by (.-)%% and casting speed by (.-)%%%.%s*$","Aumenta a velocidade de ataque corpo a corpo e à distância em {{1}}% e a velocidade de lançamento em {{2}}%."}
T[31]={"^Reduced distance at which target will attack and reduced attack speed by 20%%%.%s*$","Reduz a distância em que o alvo atacará você e reduz a velocidade de ataque em 20%."}
T[32]={"^Drains (.-)%% mana every (.-) seconds, restoring 100%% of the amount drained to you%.%s*$","Drena {{1}}% de mana a cada {{2}} segundos, restaurando para você 100% da quantidade drenada."}
T[33]={"^Armor reduced by 5%% and resistances by (.-)%.%s*$","A armadura é reduzida em 5% e as resistências em {{1}}."}
T[34]={"^Increases ranged attack speed by (.-)%% and damage dealt to creatures by (.-)%%%.%s*$","Aumenta a velocidade de ataque à distância em {{1}}% e o dano causado a criaturas em {{2}}%."}
T[35]={"^The next melee or ranged attack made against you will be made against the intervening player instead%.%s*$","O próximo ataque corpo a corpo ou à distância contra você atingirá o jogador interveniente em vez disso."}
T[36]={"^Deals (.-) Shadow damage every (.-) seconds%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} segundos."}
T[37]={"^Invisible%.%s*$","Invisível."}
T[38]={"^Damage increased by (.-)%% and your attacks deal (.-) more damage%.%s*$","O dano aumenta em {{1}}% e seus ataques causam {{2}} de dano adicional."}
T[39]={"^Gain (.-) rage per second%. Maul hits 2 additional targets%.%s*$","Ganha {{1}} de raiva por segundo. Malho atinge 2 alvos próximos adicionais."}
T[40]={"^Intimidated%. Physical damage taken increased by (.-)%%%.%s*$","Intimidado. O dano Físico recebido aumenta em {{1}}%."}
T[41]={"^Dodge chance increased by (.-)%% and chance ranged attacks hit you reduced by (.-)%%%. Reduces the duration of disorient effects by (.-)%%%.%s*$","A chance de esquiva aumenta em {{1}}%, e a chance de ataques à distância atingirem você diminui em {{2}}%. Reduz a duração dos efeitos de desorientação em {{3}}%."}
T[42]={"^Increases melee attack power by 30, armor contribution from cloth and leather items by (.-)%%, and Stamina by (.-)%%%.%s*$","Aumenta o poder de ataque corpo a corpo em 30, a contribuição de armadura de itens de tecido e couro em {{1}}% e o Vigor em {{2}}%."}
T[43]={"^Underwater breathing and increased swim speed%.%s*$","Permite respirar debaixo d'água e aumenta a velocidade de natação."}
T[44]={"^Reduces spell damage taken by (.-)%% and allows (.-)%% of your mana regeneration to continue while casting%.  Only one type of Armor spell can be active on the Mage at any time%.  Lasts (.-)%.%s*$","Reduz o dano por feitiço recebido em {{1}}% e permite que se continue regenerando {{2}}% da mana enquanto lança feitiços. Só pode estar ativa uma classe de feitiço de armadura por vez no Mago. Dura {{3}}."}
T[45]={"^Warded against Fear and Horror effects%.%s*$","Protegido contra os efeitos de Temor e Horror."}
T[46]={"^Spell casting speed increased by (.-)%% and cost of magical spells and abilities reduced by (.-)%%%.%s*$","Aumenta a velocidade de lançamento em {{1}}% e reduz o custo dos feitiços mágicos e habilidades em {{2}}%."}
T[47]={"^Increased damage and cost for your magical spells and abilities%.%s*$","Aumenta o dano e o custo para seus feitiços mágicos e habilidades."}
T[48]={"^Immune to stuns and gain (.-)%% of total mana every (.-) sec%.%s*$","Imune a atordoamentos e recupera {{1}}% da mana total a cada {{2}} segundos."}
T[49]={"^While active, casting a melee ability that deals damage will cause a Sweeping Strike, dealing 40%% weapon damage to 5 nearby enemies, further increased by attack power%.%s*$","Enquanto estiver ativo, lançar uma habilidade de corpo a corpo que causa dano provocará um Golpe Circular, causando 40% de dano da arma a 5 inimigos próximos, aumentado pelo poder de ataque."}
T[50]={"^Casting speed of all spells increased by (.-)%%%.%s*$","A velocidade de lançamento de todos os feitiços aumenta em {{1}}%."}
T[51]={"^Untrackable and melee attack power for the pet and owner increased by 5%%%.%s*$","Você não pode ser rastreado, e o poder de ataque corpo a corpo do mascote e do dono aumenta em 5%."}
T[52]={"^Melee attack speed increased by (.-)%%%.  Weapon attacks strike an additional nearby opponent%.%s*$","Velocidade de ataque de corpo a corpo aumentada em {{1}}%. Os ataques com armas golpeiam um oponente adicional próximo."}
T[53]={"^Critical strike chance, damage and range of your next direct damage Rogue ability increased%.%s*$","chance de acerto crítico, dano e alcance de sua próxima habilidade de dano direto do Ladino aumentados."}
T[54]={"^The mana cost of your next Greater Heal, Mind Blast or Power Word: Shield is reduced by (.-)%% and is granted an additional effect%.%s*$","O custo de mana de seu próximo Cura Maior, Impacto Mental ou Palavra de Poder: Escudo é reduzido em {{1}}% e recebe um efeito adicional."}
T[55]={"^(.-) Holy damage every (.-) seconds%. Incoming periodic healing and absorbs reduced by 30%%%.%s*$","{{1}} de dano Sagrado a cada {{2}} segundos. A cura periódica recebida e os efeitos de absorção diminuem em 30%."}
T[56]={"^You have a (.-)%% chance to gain Spirit Tap after killing a target that yields experience or honor%. \n\nYour Spirit is increased by (.-)%% and your mana will regenerate at (.-)%% rate while casting%. \nLasts (.-)%.%s*$","Você tem {{1}}% de chance de obter o benefício de Transfusão de Espírito ao matar um alvo que concede a você experiência ou honra.\n\nSeu Espírito aumenta em {{2}}% e sua mana se regenerará a {{3}}% da velocidade normal enquanto lança feitiços.\nDura {{4}}."}
T[57]={"^You have a (.-)%% chance to gain Spirit Tap after killing a target that yields experience or honor%. \n\nYour Spirit is increased by (.-)%% and your mana will regenerate at (.-)%% rate while casting%. \nLasts (.-)%.\nThis does not stack with similar effects%.%s*$","Tem {{1}}% de chance de obter o benefício de Transfusão de Espírito ao matar um alvo que concede a você experiência ou honra.\n\nSeu Espírito aumenta em {{2}}% e sua mana se regenerará a {{3}}% da velocidade normal enquanto lança feitiços.\nDura {{4}}.\nEste benefício não acumula com outros semelhantes."}
T[58]={"^(.-)%% of single%-target Shadow spell damage caused with priest spells by the caster heals the caster and (.-)%% heals the group%.%s*$","{{1}}% do dano de Sombra causado pelo conjurador com feitiços de Sacerdote contra um único alvo cura o próprio conjurador, e {{2}}% cura o grupo."}
T[59]={"^Shadow damage you deal increased by (.-)%%%. You may not cast healing, or Priest Holy spells while in this form%. Grants Shadow Word: Pain, Devouring Plague and Vampiric Touch the ability to benefit from haste%.%s*$","O dano de Sombra causado aumenta em {{1}}%. Nesta forma, você não pode lançar feitiços de cura nem feitiços Sagrados de Sacerdote. Palavra Sombria: Dor, Peste Devoradora e Toque Vampírico passam a se beneficiar de Aceleração."}
T[60]={"^Shadow damage you deal increased by (.-)%%%. You may not cast healing, or Priest Holy spells while in this form%. Grants the periodic damage from your Shadow Word: Pain, Devouring Plague, and Vampiric Touch spells the ability to critically hit and benefit from haste%.%s*$","O dano de Sombra causado aumenta em {{1}}%. Nesta forma, você não pode lançar feitiços de cura nem feitiços Sagrados de Sacerdote. O dano periódico de Palavra Sombria: Dor, Peste Devoradora e Toque Vampírico pode causar acertos críticos e se beneficiar de Aceleração."}
T[61]={"^Your next Shaman Nature spell with a casting time less than 10 secs will be an instant cast spell%.%s*$","Seu próximo feitiço de Natureza do xamã com tempo de lançamento inferior a 10 s será um feitiço instantâneo."}
T[62]={"^Damage you take has a chance to entangle the enemy%.%s*$","O dano recebido tem chance de enraizar o inimigo."}
T[63]={"^Each of your damage, healing spells and auto attacks has a chance of causing you to enter a Clearcasting state%.%s*$","Cada um dos seus feitiços de dano, cura e ataques automáticos têm chance de fazer você entrar em um estado de Conjuração Livre."}
T[64]={"^Your next Druid Nature spell will be an instant cast spell%.%s*$","Seu próximo feitiço de Natureza do Druida será um feitiço de lançamento instantâneo."}
T[65]={"^Reduces the chance for melee and ranged attacks to hit you by (.-)%%, (.-)%% chance to deflect spells, unable to attack and silenced%.  Movement speed increased by 30%%%s*$","Reduz em {{1}}% a chance de ataques corpo a corpo e à distância atingirem você e concede {{2}}% de chance de desviar feitiços. Você não pode atacar e fica silenciado. A velocidade de movimento aumenta em 30%."}
T[66]={"^Reduces the chance for melee and ranged attacks to hit you by (.-)%%, (.-)%% chance to deflect spells, unable to attack and silenced%.%s*$","Reduz em {{1}}% a chance de ataques corpo a corpo e à distância atingirem você e concede {{2}}% de chance de desviar feitiços. Você não pode atacar e fica silenciado."}
T[67]={"^Damage done reduced by (.-)%%%. Falling asleep after the duration ends%.%s*$","O dano causado é reduzido em {{1}}%. Adormece quando termina o tempo de duração."}
T[68]={"^Melee attacks have a chance to immobilize for (.-)%.%s*$","Os ataques corpo a corpo têm uma chance de imobilizar durante {{1}}."}
T[69]={"^Melee auto attacks have a chance to heal you%.%s*$","Os ataques corpo a corpo automáticos têm uma chance de curá-lo."}
T[70]={"^Melee auto attacks have a chance to restore mana%.%s*$","Os ataques automáticos corpo a corpo têm uma chance de restaurar mana."}
T[71]={"^Critical effect chance of next Holy spell increased by (.-)%% and its healing by (.-)%%%.%s*$","A chance de acerto crítico do próximo feitiço Sagrado aumenta em {{1}}% e sua cura em {{2}}%."}
T[72]={"^Main hand auto attacks and Paladin melee abilities deal additional Holy damage%.%s*$","Os ataques automáticos de mão principal e as habilidades de combate corpo a corpo do Paladino causam dano Sagrado adicional."}
T[73]={"^Increases healing received by (.-)%%%. Blocked, parried, and dodged melee attacks restore (.-)%% of base mana%.%s*$","Aumenta a cura recebida em {{1}}%. Ataques corpo a corpo bloqueados, aparados ou esquivados restauram {{2}}% da Mana básica."}
T[74]={"^Block chance increased by (.-)%%%. Increased armor gained from your Shield by (.-)%%%. While active, attacks that would otherwise kill you will instead trigger your Ardent Defender%.%s*$","A chance de bloqueio aumenta em {{1}}%. Aumenta a armadura obtida por seu Escudo em {{2}}%. Enquanto estiver ativo, ataques que matariam você ativam Defensor Ardente."}
T[75]={"^Main hand auto attacks and Paladin melee abilities cause an additional (.-) Holy damage%.%s*$","Os ataques automáticos de mão principal e as habilidades de combate corpo a corpo do Paladino causam {{1}} de dano Sagrado adicional."}
T[76]={"^All damage taken is reduced by (.-)%%%.  While protected, damaging attacks will not cause spellcasting delays%.%s*$","Todo dano recebido é reduzido em {{1}}%. Enquanto dispuser de proteção, os ataques não causarão atrasos na conjuração."}
T[77]={"^Reduces damage taken by (.-)%% %((.-)%% versus players%)%. When this effect expires, you will be healed for 50%% %(25%% versus players%) of the damage taken while active%.%s*$","Reduz o dano recebido em {{1}}% ({{2}}% contra jogadores). Quando este efeito expirar, curará você por 50% (25% contra jogadores) do dano recebido enquanto estiver ativo."}
T[78]={"^Armor contribution from cloth and leather items is increased by (.-)%%, damage taken while stunned is reduced by (.-)%%%. In additon, single target spell criticals have a chance to instantly regenerate (.-)%% of your total mana%. The Moonkin can not cast healing spells while shapeshifted%.%s*$","A contribuição à armadura dos itens de tecido e couro aumenta em {{1}}%, o dano recebido enquanto estiver atordoado é reduzido em {{2}}%. Além disso, os acertos críticos de feitiços de um único alvo têm uma chance de regenerar instantaneamente {{3}}% de sua mana total. O Luniscante não pode lançar feitiços de cura enquanto está transformado."}
T[79]={"^Increases spell critical effect chance by (.-)%%%.%s*$","Aumenta a chance de acerto crítico dos feitiços em {{1}}%."}
T[80]={"^Increases ranged and melee critical strike chance by (.-)%%%.%s*$","Aumenta a chance de acerto crítico em corpo a corpo e à distância em {{1}}%."}
T[81]={"^Increases your total armor by (.-)%%%. Increases your spell damage by 30%% of your Stamina%. Threat increased, but your overall damage done reduced by 10%%%. Chance to block Fierce Blows increased by (.-)%%%.%s*$","Aumenta sua armadura total em {{1}}%. Aumenta seu dano mágico em 30% de seu Vigor. Aumenta a ameaça, mas reduz o dano total causado por 10%. A chance de bloquear Golpes Férreos aumenta em {{2}}%."}
T[82]={"^Increases hit chance equal to %$%?s30143|s30144|s30145%[%]%[(.-)%]%$%?s30143%[(.-)%]%[%]%$%?s30144%[(.-)%]%[%]%$%?s30145%[(.-)%]%[%]%% of your Spirit%. Your damage spells have a chance to heal you for (.-)%% of your base health%.%s*$","Aumenta a chance de acerto igual a $?s30143|s30144|s30145[][{{1}}]$?s30143[{{2}}][]$?s30144[{{3}}][]$?s30145[{{4}}][]% de seu Espírito. Seus feitiços nocivos têm uma chance de curar você em {{5}}% de sua vida base."}
T[83]={"^Causes (.-) Fire damage to attackers%.  Chance to receive a critical hit reduced by (.-)%%%.  Critical strike rating increased by (.-)%% of Intellect%.%s*$","Causa {{1}} de dano de Fogo aos atacantes. Chance de receber um acerto crítico reduzida em {{2}}%. Índice de acerto crítico aumentado em {{3}}% do Intelecto."}
T[84]={"^Successful melee attacks have a chance to regenerate mana equal to (.-)%% of your attack power%.%s*$","Os ataques corpo a corpo bem-sucedidos têm uma chance de regenerar mana igual a {{1}}% de seu poder de ataque."}
T[85]={"^Resisting all hostile spells%.%s*$","Resistindo a todos os feitiços hostis."}
T[86]={"^Transfers melee attacks made against you and (.-)%% of threat generated to original caster instead%.%s*$","Transfere para o conjurador original os ataques corpo a corpo realizados contra você e {{1}}% da ameaça gerada."}
T[87]={"^Main hand auto and Paladin melee abilities cause Holy damage over (.-)%.%s*$","Os golpes automáticos de mão principal e as habilidades de ataque corpo a corpo do Paladino causam dano Sagrado durante {{1}}."}
T[88]={"^Reduces the duration of any Disorient, Fear, Incapacitate or Polymorph effects by (.-)%% on the caster%. Any Paladin Aura provides immunity to Silence and Interrupt effects%. \nEffectiveness of all auras increased by (.-)%%%.%s*$","Reduz a duração de qualquer efeito Desorientar, Temor, Incapacitar ou Polimorfismo no conjurador em {{1}}%. Qualquer Aura do Paladino concede imunidade a efeitos de silêncio e interrupção.\nEficácia de todas as auras aumentada em {{2}}%."}
T[89]={"^Mana cost of all spells reduced by (.-)%%%.\nCritical effect chance of Holy healing spells increased by 20%%%.%s*$","Reduz o custo de mana de todos os feitiços em {{1}}%.\nAumenta em 20% a chance de acerto crítico dos feitiços de cura Sagrada."}
T[90]={"^All damage increased by (.-)%%%.%s*$","Todo dano aumenta em {{1}}%."}
T[91]={"^All Holy damage and Holy healing caused increased by (.-)%%%.%s*$","Aumenta todo o dano Sagrado e toda a cura Sagrada realizados em {{1}}%."}
T[92]={"^Chance to apply Deadly Poison increased by (.-)%% and Instant Poison by (.-)%%%.%s*$","Aumenta a chance de aplicar Veneno Mortal em {{1}}% e Veneno Instantâneo em {{2}}%."}
T[93]={"^Immune to Polymorph effects%.\nMovement speed increased by (.-)%% and allows you to fly%.%s*$","Imune aos efeitos de Polimorfismo.\nVelocidade de movimento aumentada em {{1}}% e permite que você voe."}
T[94]={"^Your ranged and melee attacks have a chance to regenerate a percentage of your base mana, but your total damage and healing done is reduced by (.-)%%%. In addition, you gain (.-)%% of maximum mana every (.-) sec%.%s*$","Seus ataques corpo a corpo e à distância têm chance de restaurar uma porcentagem da Mana básica, mas o dano e a cura realizados diminuem em {{1}}%. Além disso, você recupera {{2}}% da mana máxima a cada {{3}} segundos."}
T[95]={"^(.-) Shadow damage every (.-) seconds%. Priest's party or raid members gain 1%% of their maximum mana per 5 sec when the caster deals damage from Mind Blast%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} segundos. Os membros do grupo ou raide do Sacerdote recuperam 1% da mana máxima a cada 5 segundos quando o conjurador causa dano com Impacto Mental."}
T[96]={"^Attack power increased%.%s*$","Poder de Ataque aumentou."}
T[98]={"^Reduces all damage by (.-)%%, and you regenerate (.-)%% mana every (.-) sec for (.-)%.  Cannot attack or cast spells%.%s*$","Reduz todo dano em {{1}}%, e você regenera {{2}}% mana a cada {{3}} s durante {{4}}. Você não pode atacar nem lançar feitiços."}
T[100]={"^Causing shadow damage to all targets around the target within (.-) yards%.%s*$","Causa dano de Sombra todos os alvos ao redor do alvo em um raio de {{1}} m."}
T[101]={"^Damage taken from Warlock Shadow damage%-over%-time effects increased by (.-)%%%.%s*$","O dano recebido por efeitos de dano ao longo do tempo da Magia Sombria aumenta em {{1}}%."}
T[102]={"^Stamina increased by (.-)%%%.\nArmor contribution from cloth, leather, mail and plate items increased by (.-)%%%.\nDamage taken reduced by (.-)%%%.%s*$","Vigor aumentado em {{1}}%.\nA contribuição de armadura de itens de tecido, couro, malha e placas aumenta em {{2}}%.\nDano recebido reduzido em {{3}}%."}
T[103]={"^Attack speed increased (.-)%%%.\nMovement speed increased by (.-)%%%.\nGlobal cooldown on all Deathknight abilities reduced by (.-)%.1 sec%.%s*$","Velocidade de ataque aumentada em {{1}}%.\nVelocidade de movimento aumentada em {{2}}%.\nA recarga global de todas as habilidades de Cavaleiro da Morte diminui em {{3}}.1 segundos."}
