T[7092]={"^Dealing damage with |cFFFFFFFFFireball|r or |cFFFFFFFFPyroblast|r grants |cFFFFFFFFLunar Flames|r%.%s*$","Causar dano com |cFFFFFFFFBola de Fogo|r ou |cFFFFFFFFPiroexplosão|r concede |cFFFFFFFFChamas Lunares|r."}
