T[11179]={"^All damage taken reduced by (.-)%%%.%s*$","Todos seus dano recebido é reduzido em {{1}}%."}
T[11180]={"^Dealing 30%% of the damage dealt by Putrefy%.%s*$","Causa 30% do dano causado por Putrefazer."}
